public class Div680 {
    static int totalCount, modulus, shift, memo[][][];

    static int countSequences(int completed, int index, int diff) {
        if (index == n)
            return diff > 0 ? 1 : 0;
        if (memo[completed][index][diff + shift] != -1)
            return memo[completed][index][diff + shift];
        int remaining = n - index;
        int sum = 0;
        for (int leftPart = 0; leftPart < remaining; leftPart++) {
            for (int rightPart = (completed == 1 ? 0 : leftPart); rightPart < remaining; rightPart++) {
                sum += countSequences(completed | (leftPart < rightPart ? 1 : 0), index + 1, diff + leftPart - rightPart);
                sum %= modulus;
            }
        }
        return memo[completed][index][diff + shift] = sum;
    }

    static long computeTotal(int i) {
        if (i == n - 1)
            return 0;
        long totalWays = (n - i) * 1L * computeTotal(i + 1);
        totalWays %= modulus;
        for (int l = 0; l < n - i; l++) {
            for (int r = l + 1; r < n - i; r++) {
                totalWays += countSequences(1, i + 1, l - r);
                totalWays %= modulus;
            }
        }
        return totalWays;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        n = sc.nextInt();
        modulus = sc.nextInt();
        shift = n * (n - 1);
        memo = new int[2][n][2 * shift + 1];

        for (int[][] layer1 : memo)
